#!/usr/bin/env python3
"""PreToolUse hook (Write|Edit|NotebookEdit): warns (or refuses) when a file generated by skillsync is edited by hand.

A guard against a slip, not a security boundary: `sed -i`, redirections and other writes outside these tools get past it.
Generated files are recognised ONLY by explicit rules (the hook is standalone, it does not import the generator):
  (a) path patterns relative to the git root: .claude/agents/*, .claude/skills/*, .agents/*, .codex/*, .github/copilot-instructions.md,
      .github/skills/*, .github/agents/* (the same names below another directory are not generated);
  (b) a symlink whose real path leaves the project (a link into a library layer: the write edits the library);
  (c) AGENTS.md, only when the edit touches the block between SKILLSYNC:CODEX-BEGIN and SKILLSYNC:CODEX-END (the rest is the user's);
  (d) CLAUDE.md, only when it holds the generator marker SKILLSYNC:BASE-END (otherwise skipped);
  (e) an existing file whose first lines carry the header "Generated by skillsync" (Codex TOML).
Paths are normalised (relative to the cwd, backslashes, letter case on Windows).

Usage (set by `skillsync link`): guard-generated.py [--mode warn|deny|off]; missing = warn, unknown = off; stdin = the hook JSON (UTF-8).
warn: additionalContext "change the library and run `skillsync link`" (exit 0); deny: exit 2 and the same text on stderr; off: silence.
Every other error is fail-open (exit 0). No network, writes nothing.
"""
import json
import os
import re
import subprocess
import sys

TOOLS = ('Write', 'Edit', 'NotebookEdit')
BEGIN, END = 'SKILLSYNC:CODEX-BEGIN', 'SKILLSYNC:CODEX-END'
BASE_END = 'SKILLSYNC:BASE-END'
HEADER = 'generated by skillsync'
WINDOWS = os.name == 'nt'
MAX_READ = 4 * 1024 * 1024
BLOCK = re.compile(r'<!--\s*' + BEGIN + r'\s*-->.*?<!--\s*' + END + r'\s*-->', re.DOTALL)


def fold(text):
    return text.lower() if WINDOWS else text


def mode_from_args(args):
    value = 'warn'
    for index, arg in enumerate(args):
        if arg == '--mode' and index + 1 < len(args):
            value = args[index + 1]
        elif arg.startswith('--mode='):
            value = arg[len('--mode='):]
    return value if value in ('warn', 'deny', 'off') else 'off'


def git_root(cwd):
    done = subprocess.run(['git', '-C', cwd, 'rev-parse', '--show-toplevel'], capture_output=True, timeout=3,
                          stdin=subprocess.DEVNULL, env=dict(os.environ, GIT_OPTIONAL_LOCKS='0'))
    top = done.stdout.decode('utf-8', 'replace').strip() if done.returncode == 0 else ''
    return top if top and os.path.isdir(top) else None


def relative_parts(root, path):
    """Parts of `path` relative to `root`, or None when it lies outside. The directory is resolved, the file name itself is not."""
    real_root = os.path.realpath(root)
    head, tail = os.path.split(path)
    candidates = (os.path.join(os.path.realpath(head), tail), path)
    for candidate in candidates:
        for base in (real_root, os.path.normpath(root)):
            rel = os.path.relpath(candidate, base) if _same_drive(candidate, base) else None
            if rel and rel != '.' and not rel.startswith('..') and not os.path.isabs(rel):
                return [part for part in rel.replace('\\', '/').split('/') if part]
    return None


def _same_drive(first, second):
    return os.path.splitdrive(first)[0].lower() == os.path.splitdrive(second)[0].lower()


def pattern_match(parts):
    """Rule (a). `parts` are relative to the git root."""
    low = [fold(part) for part in parts]
    if len(low) >= 3 and low[0] == '.claude' and low[1] in ('agents', 'skills'):
        return True
    if len(low) >= 2 and low[0] in ('.agents', '.codex'):
        return True
    if low == ['.github', 'copilot-instructions.md']:
        return True
    return len(low) >= 3 and low[0] == '.github' and low[1] in ('skills', 'agents')


def read_text(path):
    try:
        if os.path.getsize(path) > MAX_READ:
            return None
        with open(path, 'rb') as handle:
            return handle.read().decode('utf-8', 'replace').replace('\r\n', '\n')
    except OSError:
        return None


def norm(value):
    return value.replace('\r\n', '\n') if isinstance(value, str) else None


def agents_block_touched(path, tool, tool_input):
    """Rule (c): does the edit change the Codex block of AGENTS.md?"""
    text = read_text(path)
    if text is None:
        return False
    block = BLOCK.search(text)
    if not block:
        return False
    if tool == 'Write':
        content = norm(tool_input.get('content'))
        if content is None:
            return False
        new_block = BLOCK.search(content)
        return new_block is None or new_block.group(0) != block.group(0)
    if tool == 'Edit':
        old, new = norm(tool_input.get('old_string')), norm(tool_input.get('new_string')) or ''
        if BEGIN in (old or '') + new or END in (old or '') + new:
            return True
        if not old:
            return False
        start = text.find(old)
        while start != -1:
            if start < block.end() and start + len(old) > block.start():
                return True
            start = text.find(old, start + 1)
    return False


def classify(root, path, tool, tool_input):
    """Returns (kind, relative path) of the generated file or None. kind: 'pattern', 'layer', 'instruction', 'header'."""
    parts = relative_parts(root, path)
    if parts is None:
        return None
    rel = '/'.join(parts)
    if pattern_match(parts):
        return ('instruction' if fold(parts[0]) in ('.claude', '.github') else 'pattern', rel)
    try:
        if os.path.realpath(path) and relative_parts(root, os.path.realpath(path)) is None:
            return ('layer', rel)
    except OSError:
        pass
    if len(parts) == 1 and fold(parts[0]) == fold('AGENTS.md') and agents_block_touched(path, tool, tool_input):
        return ('instruction', rel)
    if len(parts) == 1 and fold(parts[0]) == fold('CLAUDE.md'):
        text = read_text(path)
        if text is not None and BASE_END in text:
            return ('instruction', rel)
        return None
    try:
        if os.path.isfile(path):
            with open(path, 'rb') as handle:
                first = handle.read(1024).decode('utf-8', 'replace').splitlines()[:3]
            for line in first:
                if HEADER in line.lower() and line.lstrip().startswith(('#', '//', '<!--', '/*', ';')):
                    return ('header', rel)
    except OSError:
        pass
    return None


def message(kind, rel):
    if kind == 'layer':
        return (f'{rel} jest dowiązaniem do warstwy biblioteki: zapis przez nie zmienia bibliotekę, nie projekt. '
                'Zmień bibliotekę celowo (lokalne instrukcje przenosi `skillsync push`) i uruchom `skillsync link`.')
    text = f'{rel} jest generowany przez skillsync; ręczna zmiana zginie przy kolejnym linku. Zmień bibliotekę i uruchom `skillsync link`.'
    if kind == 'instruction':
        text += ' Zmiany lokalnych instrukcji przenosi do biblioteki `skillsync push`.'
    return text


def main():
    mode = mode_from_args(sys.argv[1:])
    if mode == 'off':
        return 0
    payload = json.loads(sys.stdin.buffer.read().decode('utf-8', 'replace'))
    if not isinstance(payload, dict) or payload.get('tool_name') not in TOOLS:
        return 0
    tool = payload['tool_name']
    tool_input = payload.get('tool_input')
    cwd = payload.get('cwd')
    if not isinstance(tool_input, dict) or not isinstance(cwd, str) or not os.path.isdir(cwd):
        return 0
    file_path = tool_input.get('file_path')
    if not isinstance(file_path, str) or not file_path:
        file_path = tool_input.get('notebook_path')
    if not isinstance(file_path, str) or not file_path:
        return 0
    file_path = file_path.replace('\\', '/') if WINDOWS else file_path
    path = os.path.normpath(file_path if os.path.isabs(file_path) else os.path.join(cwd, file_path))
    root = git_root(cwd)
    if not root:
        return 0
    found = classify(root, path, tool, tool_input)
    if not found:
        return 0
    text = message(*found)
    if mode == 'deny':
        sys.stderr.buffer.write((text + '\n').encode('utf-8'))
        return 2
    out = {'hookSpecificOutput': {'hookEventName': 'PreToolUse', 'additionalContext': text}}
    sys.stdout.buffer.write(json.dumps(out, ensure_ascii=False).encode('utf-8'))
    return 0


if __name__ == '__main__':
    try:
        code = main()
    except Exception:  # fail-open: a hook error must never block a tool
        code = 0
    sys.exit(code)
